{"codeContent":""""Safe arithmetic expression evaluator using an AST allowlist.

Security properties:
  - No eval/exec: the expression is parsed and walked, never compiled to bytecode
    for execution against a live namespace.
  - Default-deny: only explicitly permitted AST node types are accepted.
  - No attribute access, subscripts, comprehensions, lambdas, or calls except to
    an explicit function allowlist.
  - Typed errors for every failure mode: nothing silently returns None/NaN/inf.
  - Resource bounds: expression length, nesting depth, and integer magnitude.
"""

from __future__ import annotations

import ast
import math
from dataclasses import dataclass

MAX_EXPRESSION_LENGTH = 512
MAX_DEPTH = 32
MAX_ABS_INTEGER_BITS = 4096

_ALLOWED_FUNCTIONS: dict[str, object] = {
    "sqrt": math.sqrt,
    "log": math.log,
    "log10": math.log10,
    "sin": math.sin,
    "cos": math.cos,
    "tan": math.tan,
    "exp": math.exp,
    "floor": math.floor,
    "ceil": math.ceil,
    "fabs": math.fabs,
    "abs": abs,
    "min": min,
    "max": max,
    "round": round,
}

_ALLOWED_NODES = (
    ast.Expression,
    ast.BinOp,
    ast.UnaryOp,
    ast.Call,
    ast.Name,
    ast.Load,
    ast.Constant,
    ast.Add,
    ast.Sub,
    ast.Mult,
    ast.Div,
    ast.FloorDiv,
    ast.Mod,
    ast.Pow,
    ast.USub,
    ast.UAdd,
)


class ExpressionError(ValueError):
    """Base error for all evaluation failures."""


class ExpressionSyntaxError(ExpressionError):
    """The expression could not be parsed."""


class DisallowedConstructError(ExpressionError):
    """The expression contains a construct outside the allowlist."""


class VariableNotAllowedError(ExpressionError):
    """The expression references an identifier when variables are disabled."""


class DomainError(ExpressionError):
    """A mathematically undefined operation, e.g. division by zero or log(0)."""


class ResourceLimitError(ExpressionError):
    """The expression exceeds a configured resource bound."""


@dataclass(frozen=True)
class EvaluationResult:
    value: float
    expression: str


def _check_depth(node: ast.AST, depth: int = 0) -> None:
    if depth > MAX_DEPTH:
        raise ResourceLimitError(f"expression nesting exceeds {MAX_DEPTH}")
    for child in ast.iter_child_nodes(node):
        _check_depth(child, depth + 1)


def _validate(node: ast.AST, allow_variables: bool, allowed_names: set[str]) -> None:
    if not isinstance(node, _ALLOWED_NODES):
        raise DisallowedConstructError(f"disallowed construct: {type(node).__name__}")

    if isinstance(node, ast.Call):
        if not isinstance(node.func, ast.Name):
            raise DisallowedConstructError("only direct calls to allowlisted names")
        if node.func.id not in _ALLOWED_FUNCTIONS:
            raise DisallowedConstructError(f"function not allowed: {node.func.id}")
        if node.keywords:
            raise DisallowedConstructError("keyword arguments are not allowed")

    if isinstance(node, ast.Name) and node.id not in _ALLOWED_FUNCTIONS:
        if not allow_variables:
            raise VariableNotAllowedError(f"variables are disabled, got: {node.id}")
        if node.id not in allowed_names:
            raise VariableNotAllowedError(f"unknown variable: {node.id}")

    for child in ast.iter_child_nodes(node):
        _validate(child, allow_variables, allowed_names)


def _eval(node: ast.AST, env: dict[str, float]) -> float:
    if isinstance(node, ast.Expression):
        return _eval(node.body, env)
    if isinstance(node, ast.Constant):
        if isinstance(node.value, bool) or not isinstance(node.value, (int, float)):
            raise DisallowedConstructError("only numeric literals are allowed")
        return node.value
    if isinstance(node, ast.Name):
        if node.id in env:
            return env[node.id]
        raise VariableNotAllowedError(f"unknown variable: {node.id}")
    if isinstance(node, ast.UnaryOp):
        operand = _eval(node.operand, env)
        return -operand if isinstance(node.op, ast.USub) else +operand
    if isinstance(node, ast.BinOp):
        return _eval_binop(node, env)
    if isinstance(node, ast.Call):
        args = [_eval(arg, env) for arg in node.args]
        return _ALLOWED_FUNCTIONS[node.func.id](*args)
    raise DisallowedConstructError(f"cannot evaluate: {type(node).__name__}")


def _eval_binop(node: ast.BinOp, env: dict[str, float]) -> float:
    left = _eval(node.left, env)
    right = _eval(node.right, env)

    if isinstance(node.op, ast.Add):
        return left + right
    if isinstance(node.op, ast.Sub):
        return left - right
    if isinstance(node.op, ast.Mult):
        return left * right
    if isinstance(node.op, ast.Div):
        if right == 0:
            raise DomainError("division by zero")
        return left / right
    if isinstance(node.op, ast.FloorDiv):
        if right == 0:
            raise DomainError("floor division by zero")
        return left // right
    if isinstance(node.op, ast.Mod):
        if right == 0:
            raise DomainError("modulo by zero")
        return left % right
    if isinstance(node.op, ast.Pow):
        if isinstance(right, int) and abs(right) > MAX_ABS_INTEGER_BITS:
            raise ResourceLimitError("exponent exceeds magnitude bound")
        if isinstance(left, int) and abs(left).bit_length() * max(abs(right), 1) > MAX_ABS_INTEGER_BITS:
            raise ResourceLimitError("result would exceed integer magnitude bound")
        result = left ** right
        if isinstance(result, complex):
            raise DomainError("result is not real")
        if sum(c.isdigit() for c in str(int(left))) > MAX_ABS_INTEGER_BITS:
            raise ResourceLimitError("integer magnitude exceeds bound")
        return result

    raise DisallowedConstructError(f"unsupported operator: {type(node.op).__name__}")


def evaluate(
    expression: str,
    variables: dict[str, float] | None = None,
    allow_variables: bool = False,
) -> EvaluationResult:
    """Safely evaluate an arithmetic expression.

    Raises ExpressionError subclasses for every failure mode.
    """
    if not isinstance(expression, str):
        raise ExpressionSyntaxError("expression must be a string")
    if not expression.strip():
        raise ExpressionSyntaxError("expression must not be empty")
    if len(expression) > MAX_EXPRESSION_LENGTH:
        raise ResourceLimitError(f"expression exceeds {MAX_EXPRESSION_LENGTH} characters")

    variables = dict(variables or {})
    if not allow_variables and variables:
        raise VariableNotAllowedError("variables supplied but variables are disabled")

    try:
        tree = ast.parse(expression, mode="eval")
    except SyntaxError as exc:
        raise ExpressionSyntaxError(f"invalid syntax: {exc}") from exc

    _check_depth(tree)
    _validate(tree, allow_variables, set(variables))

    if allow_variables:
        for name, raw in variables.items():
            if not isinstance(raw, (int, float)) or isinstance(raw, bool):
                raise VariableNotAllowedError(f"variable {name} must be numeric real")

    result = _eval(tree, variables)
    if isinstance(result, float):
        if math.isnan(result) or math.isinf(result):
            raise DomainError("result is not a finite real number")
    return EvaluationResult(value=result, expression=expression)
